content:
:root {
  --bg-primary: #f8fafc;
  --bg-surface: #ffffff;
  --bg-subtle: #f1f5f9;
  --text-main: #0f172a;
  --text-secondary: #475569;
  --text-muted: #94a3b8;
  --accent-primary: #3b82f6;
  --accent-hover: #2563eb;
  --accent-light: #eff6ff;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
  --danger-light: #fef2f2;
  --border-color: #e2e8f0;
  --border-focus: #3b82f6;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-primary);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

/* アプリ全体のコンテナ */
.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 16px 48px;
}

/* ヘッダー */
.app-header {
  margin-bottom: 24px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border-color);
}

.header-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.025em;
  display: flex;
  align-items: center;
  gap: 8px;
}

.header-subtitle {
  font-size: 0.95rem;
  color: var(--text-secondary);
  margin-top: 6px;
}

/* メインレイアウト（グラフ領域と一覧・フォーム領域） */
.main-layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
  align-items: start;
}

@media (min-width: 900px) {
  .main-layout {
    grid-template-columns: 1fr 1fr;
  }
}

/* セクション設定 */
.chart-section {
  display: flex;
  flex-direction: column;
  gap: 20px;
  position: sticky;
  top: 24px;
}

.list-section {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* カード共通スタイル */
.chart-card,
.list-card,
.form-card {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
}

.chart-card:hover,
.list-card:hover,
.form-card:hover {
  box-shadow: var(--shadow-md);
}

/* グラフ関連 */
.chart-wrapper {
  width: 100%;
  height: 320px;
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  touch-action: pan-y;
}

.center-details {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 16px 20px;
  margin-top: 8px;
  text-align: center;
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
}

.detail-name {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 4px;
}

.detail-amount {
  font-size: 1.6rem;
  font-weight: 800;
  color: var(--accent-primary);
  letter-spacing: -0.02em;
}

.detail-percent {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-secondary);
  margin-top: 2px;
}

.detail-memo {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px dashed var(--border-color);
  font-style: italic;
}

.detail-hint {
  font-size: 0.85rem;
  color: var(--text-muted);
  text-align: center;
  margin-top: 8px;
}

/* リストカード */
.card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border-color);
}

.card-title {
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--text-main);
}

.total-badge {
  background-color: var(--accent-light);
  color: var(--accent-hover);
  padding: 4px 12px;
  border-radius: 9999px;
  font-size: 0.9rem;
  font-weight: 700;
}

/* 支出項目リスト */
.expense-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-height: 480px;
  overflow-y: auto;
  padding-right: 4px;
}

.expense-list::-webkit-scrollbar {
  width: 6px;
}

.expense-list::-webkit-scrollbar-thumb {
  background-color: var(--border-color);
  border-radius: 9999px;
}

.expense-item {
  display: flex;
  align-items: center;
  padding: 12px 14px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  background-color: var(--bg-surface);
  cursor: pointer;
  transition: var(--transition);
  user-select: none;
}

.expense-item:hover {
  background-color: var(--bg-subtle);
  transform: translateX(2px);
}

.expense-item-active {
  background-color: var(--accent-light);
  border-color: var(--accent-primary);
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2);
}

.item-color-indicator {
  width: 14px;
  height: 14px;
  border-radius: 4px;
  margin-right: 12px;
  flex-shrink: 0;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.1);
}

.item-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.item-name {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-main);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.item-percent {
  font-size: 0.8rem;
  color: var(--text-muted);
}

.item-amount {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text-main);
  margin-right: 12px;
  white-space: nowrap;
}

.item-delete-btn {
  background: transparent;
  border: none;
  color: var(--text-muted);
  width: 32px;
  height: 32px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: var(--transition);
  flex-shrink: 0;
}

.item-delete-btn:hover {
  background-color: var(--danger-light);
  color: var(--danger-color);
}

/* 追加フォーム */
.form-card {
  background-color: var(--bg-surface);
}

.form-row {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
  margin-bottom: 12px;
}

@media (min-width: 480px) {
  .form-row {
    grid-template-columns: 1fr 1fr;
  }
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 12px;
}

.form-label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.form-input,
.form-select {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  font-size: 0.95rem;
  background-color: var(--bg-surface);
  color: var(--text-main);
  transition: var(--transition);
  font-family: inherit;
}

.form-input:focus,
.form-select:focus {
  outline: none;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.color-picker-preview {
  display: flex;
  align-items: center;
  gap: 8px;
}

.btn-submit {
  width: 100%;
  padding: 12px 16px;
  background-color: var(--accent-primary);
  color: #ffffff;
  border: none;
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  box-shadow: 0 2px 4px rgba(59, 130, 246, 0.2);
}

.btn-submit:hover {
  background-color: var(--accent-hover);
  box-shadow: 0 4px 6px rgba(59, 130, 246, 0.3);
}

.btn-submit:active {
  transform: translateY(1px);
}

/* レスポンシブ微調整（モバイル対応） */
@media (max-width: 480px) {
  .app-container {
    padding: 16px 12px 32px;
  }

  .header-title {
    font-size: 1.4rem;
  }

  .chart-wrapper {
    height: 260px;
  }

  .chart-card,
  .list-card,
  .form-card {
    padding: 16px 14px;
  }

  .item-amount {
    font-size: 0.95rem;
  }
}

export interface ExpenseItem {
  id: string;
  name: string;
  amount: number;
  color: string;
  memo?: string;
}

export interface ExpensePieChartProps {
  items: ExpenseItem[];
  selectedId: string | null;
  onSelect: (id: string | null) => void;
}

export interface ExpenseListProps {
  items: ExpenseItem[];
  selectedId: string | null;
  onSelect: (id: string | null) => void;
  onAddItem: (item: Omit<ExpenseItem, 'id'>) => void;
  onDeleteItem: (id: string) => void;
}

import { useMemo } from 'react';
import { ResponsiveContainer, PieChart, Pie, Cell, Tooltip } from 'recharts';
import { ExpensePieChartProps } from '../types';

const ExpensePieChart = ({ items = [], selectedId, onSelect }: ExpensePieChartProps) => {
  const totalAmount = useMemo(() => {
    return items.reduce((sum, item) => sum + item.amount, 0);
  }, [items]);

  const selectedItem = useMemo(() => {
    return items.find((item) => item.id === selectedId) || null;
  }, [items, selectedId]);

  const selectedPercentage = useMemo(() => {
    if (!selectedItem || totalAmount === 0) return 0;
    return ((selectedItem.amount / totalAmount) * 100).toFixed(1);
  }, [selectedItem, totalAmount]);

  const handlePieClick = (entry: any) => {
    if (!entry) return;
    const clickedId = entry.id;
    if (selectedId === clickedId) {
      onSelect?.(null);
    } else {
      onSelect?.(clickedId);
    }
  };

  return (
    <div className="chart-card">
      <div className="chart-wrapper">
        {items.length === 0 ? (
          <p className="detail-hint">データがありません。項目を追加してください。</p>
        ) : (
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Tooltip
                formatter={(value: number) => [`¥${value.toLocaleString()}`, '金額']}
                contentStyle={{
                  backgroundColor: '#ffffff',
                  borderRadius: '8px',
                  border: '1px solid #e2e8f0',
                  boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
                }}
              />
              <Pie
                data={items}
                dataKey="amount"
                nameKey="name"
                cx="50%"
                cy="50%"
                innerRadius={65}
                outerRadius={95}
                paddingAngle={3}
                cursor="pointer"
                onClick={handlePieClick}
              >
                {items.map((item) => {
                  const isSelected = item.id === selectedId;
                  return (
                    <Cell
                      key={item.id}
                      fill={item.color}
                      stroke={isSelected ? '#0f172a' : '#ffffff'}
                      strokeWidth={isSelected ? 3 : 1}
                      style={{
                        outline: 'none',
                        transition: 'all 0.2s ease',
                        filter: selectedId && !isSelected ? 'opacity(0.45)' : 'none',
                      }}
                    />
                  );
                })}
              </Pie>
            </PieChart>
          </ResponsiveContainer>
        )}
      </div>

      <div className="center-details">
        {selectedItem ? (
          <>
            <div className="detail-name">{selectedItem.name}</div>
            <div className="detail-amount">¥{selectedItem.amount.toLocaleString()}</div>
            <div className="detail-percent">全体の {selectedPercentage}%</div>
            {selectedItem.memo && <div className="detail-memo">{selectedItem.memo}</div>}
          </>
        ) : (
          <>
            <div className="detail-name">総支出</div>
            <div className="detail-amount">¥{totalAmount.toLocaleString()}</div>
            <div className="detail-percent">全 {items.length} 項目</div>
            <div className="detail-hint">グラフまたは一覧の項目をタップして詳細を表示</div>
          </>
        )}
      </div>
    </div>
  );
};

export default ExpensePieChart;

import { useState, useMemo } from 'react';
import { PlusCircle, Trash2 } from 'lucide-react';
import { ExpenseListProps } from '../types';

const DEFAULT_COLORS = [
  '#3b82f6', // 青
  '#ef4444', // 赤
  '#10b981', // 緑
  '#f59e0b', // 橙
  '#8b5cf6', // 紫
  '#ec4899', // ピンク
  '#06b6d4', // シアン
  '#64748b', // グレー
];

const ExpenseList = ({
  items = [],
  selectedId,
  onSelect,
  onAddItem,
  onDeleteItem,
}: ExpenseListProps) => {
  const [name, setName] = useState('');
  const [amountStr, setAmountStr] = useState('');
  const [color, setColor] = useState(DEFAULT_COLORS[0]);
  const [memo, setMemo] = useState('');

  const totalAmount = useMemo(() => {
    return items.reduce((sum, item) => sum + item.amount, 0);
  }, [items]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const parsedAmount = parseInt(amountStr, 10);
    if (!name.trim() || isNaN(parsedAmount) || parsedAmount <= 0) {
      return;
    }

    onAddItem?.({
      name: name.trim(),
      amount: parsedAmount,
      color,
      memo: memo.trim() || undefined,
    });

    setName('');
    setAmountStr('');
    setMemo('');
    // 次のカラーをランダムまたは順繰りにセット
    const nextColorIndex = (items.length + 1) % DEFAULT_COLORS.length;
    setColor(DEFAULT_COLORS[nextColorIndex]);
  };

  return (
    <div className="list-section">
      <div className="list-card">
        <div className="card-header">
          <h2 className="card-title">支出項目一覧</h2>
          <span className="total-badge">合計 ¥{totalAmount.toLocaleString()}</span>
        </div>

        {items.length === 0 ? (
          <p className="detail-hint">登録された支出項目はありません</p>
        ) : (
          <ul className="expense-list">
            {items.map((item) => {
              const isSelected = item.id === selectedId;
              const percent = totalAmount > 0 ? ((item.amount / totalAmount) * 100).toFixed(1) : '0';

              return (
                <li
                  key={item.id}
                  className={`expense-item ${isSelected ? 'expense-item-active' : ''}`}
                  onClick={() => {
                    if (isSelected) {
                      onSelect?.(null);
                    } else {
                      onSelect?.(item.id);
                    }
                  }}
                >
                  <span
                    className="item-color-indicator"
                    style={{ backgroundColor: item.color }}
                  />
                  <div className="item-info">
                    <span className="item-name">{item.name}</span>
                    <span className="item-percent">{percent}%</span>
                  </div>
                  <span className="item-amount">¥{item.amount.toLocaleString()}</span>
                  <button
                    type="button"
                    className="item-delete-btn"
                    title="項目を削除"
                    onClick={(e) => {
                      e.stopPropagation();
                      onDeleteItem?.(item.id);
                    }}
                  >
                    <Trash2 size={16} />
                  </button>
                </li>
              );
            })}
          </ul>
        )}
      </div>

      <div className="form-card">
        <div className="card-header">
          <h2 className="card-title">新規項目の追加</h2>
        </div>
        <form onSubmit={handleSubmit}>
          <div className="form-row">
            <div className="form-group">
              <label className="form-label" htmlFor="expense-name">
                項目名
              </label>
              <input
                id="expense-name"
                type="text"
                className="form-input"
                placeholder="例: カフェ代"
                value={name}
                onChange={(e) => setName(e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label className="form-label" htmlFor="expense-amount">
                金額 (円)
              </label>
              <input
                id="expense-amount"
                type="number"
                min="1"
                className="form-input"
                placeholder="例: 1500"
                value={amountStr}
                onChange={(e) => setAmountStr(e.target.value)}
                required
              />
            </div>
          </div>

          <div className="form-row">
            <div className="form-group">
              <label className="form-label" htmlFor="expense-color">
                カラー
              </label>
              <div className="color-picker-preview">
                <input
                  id="expense-color"
                  type="color"
                  className="form-input"
                  style={{ height: '42px', padding: '2px', cursor: 'pointer', maxWidth: '80px' }}
                  value={color}
                  onChange={(e) => setColor(e.target.value)}
                />
                <input
                  type="text"
                  className="form-input"
                  value={color}
                  onChange={(e) => setColor(e.target.value)}
                  pattern="^#[0-9A-Fa-f]{6}$"
                />
              </div>
            </div>
            <div className="form-group">
              <label className="form-label" htmlFor="expense-memo">
                メモ (任意)
              </label>
              <input
                id="expense-memo"
                type="text"
                className="form-input"
                placeholder="例: 週末のスタバ"
                value={memo}
                onChange={(e) => setMemo(e.target.value)}
              />
            </div>
          </div>

          <button type="submit" className="btn-submit">
            <PlusCircle size={18} />
            支出を追加する
          </button>
        </form>
      </div>
    </div>
  );
};

export default ExpenseList;

