    amount: 18000,
    color: '#f59e0b',
    memo: '電気・ガス・水道料金',
  },
  {
    id: 'exp-4',
    name: '通信費',
    amount: 9800,
    color: '#8b5cf6',
    memo: 'スマートフォン・自宅Wi-Fi',
  },
  {
    id: 'exp-5',
    name: '日用品',
    amount: 12500,
    color: '#06b6d4',
    memo: '洗剤・ドラッグストア・雑貨',
  },
  {
    id: 'exp-6',
    name: '娯楽・交際費',
    amount: 24000,
    color: '#ec4899',
    memo: 'サブスク・書籍・友人との食事',
  },
  {
    id: 'exp-7',
    name: '保険・医療費',
    amount: 11000,
    color: '#ef4444',
    memo: '生命保険料・定期受診・常備薬',
  },
];

const App = () => {
  const [items, setItems] = useState<ExpenseItem[]>(INITIAL_EXPENSES);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const handleSelect = (id: string | null) => {
    setSelectedId(id);
  };

  const handleAddItem = (newItemData: Omit<ExpenseItem, 'id'>) => {
    const newItem: ExpenseItem = {
      ...newItemData,
      id: `exp-${Date.now()}`,
    };
    setItems((prev) => [newItem, ...prev]);
    setSelectedId(newItem.id);
  };

  const handleDeleteItem = (id: string) => {
    setItems((prev) => prev.filter((item) => item.id !== id));
    if (selectedId === id) {
      setSelectedId(null);
    }
  };

  return (
    <div className="app-container">
      <header className="app-header">
        <h1 className="header-title">
          <PieChartIcon size={28} color="#3b82f6" />
          家計簿ダッシュボード
        </h1>
        <p className="header-subtitle">
          支出の内訳を円グラフで可視化。グラフの扇やリストをクリックして金額や割合を確認できます。
        </p>
      </header>

      <main className="main-layout">
        <div className="chart-section">
          <ExpensePieChart
            items={items}
            selectedId={selectedId}
            onSelect={handleSelect}
          />
        </div>

        <ExpenseList
          items={items}
          selectedId={selectedId}
          onSelect={handleSelect}
          onAddItem={handleAddItem}
          onDeleteItem={handleDeleteItem}
        />
      </main>
    </div>
  );
};

export default App;
